def main():
    rules = yara.compile(filepath=RULES, error_on_warning=True)
    fails = gaps = 0
    with tempfile.TemporaryDirectory() as d:
        for name, content, expect, label in CASES:
            path = os.path.join(d, name)
            with open(path, 'wb') as fh:
                fh.write(base64.b64decode(content))
            hits = [m.rule for m in rules.match(path)]
            if expect == 'GAP':
                gaps += 1
                print(f'GAP  {name:32s} {label}  hits={hits}')
                continue
            ok = (expect in hits) if expect else not hits
            fails += 0 if ok else 1
            print(f'{"PASS" if ok else "FAIL"} {name:32s} {label}' + ('' if ok else f'  hits={hits}'))
    print(f'\n{len(CASES) - gaps} cases checked, {gaps} documented gaps')
    print('ALL PASS' if not fails else f'{fails} FAILURE(S)')
    sys.exit(1 if fails else 0)


if __name__ == '__main__':
    main()
